CREATE TABLE IF NOT EXISTS user_wallets (user_id text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, balance bigint NOT NULL DEFAULT 0 CHECK (balance >= 0), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS coin_transactions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, amount integer NOT NULL CHECK (amount <> 0), reason text NOT NULL, idempotency_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS coin_transactions_user_date_idx ON coin_transactions(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS quest_claims (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, quest_key text NOT NULL, period_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,quest_key,period_key));
CREATE TABLE IF NOT EXISTS cosmetic_items (id text PRIMARY KEY, title text NOT NULL, description text NOT NULL DEFAULT '', category text NOT NULL, rarity text NOT NULL, price integer NOT NULL CHECK(price >= 0), preview text NOT NULL, superflip_only boolean NOT NULL DEFAULT false, available_until timestamptz);
CREATE TABLE IF NOT EXISTS cosmetic_inventory (user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, item_id text NOT NULL REFERENCES cosmetic_items(id) ON DELETE CASCADE, acquired_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,item_id));
CREATE TABLE IF NOT EXISTS cosmetic_equipped (user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, category text NOT NULL, item_id text NOT NULL REFERENCES cosmetic_items(id) ON DELETE CASCADE, PRIMARY KEY(user_id,category));
